name: Offline Docker Release

on:
  push:
    tags: ["v*"]
  # A tag push is the only way this ran, so a run that never starts — a stuck
  # queue, a cancelled job — left a tag with no release and no way back except
  # rewriting the tag. Rewriting a published ref to fix a pipeline is a bad
  # trade. This lets the same tag be built again without touching it.
  workflow_dispatch:
    inputs:
      tag:
        description: "다시 만들 릴리스 태그 (예: v0.150.0)"
        required: true

permissions:
  contents: write

jobs:
  release:
    runs-on: ubuntu-latest
    env:
      # Named once for the whole job. A dispatch runs on a branch, so
      # github.ref_name is the branch and every step that reads it would build
      # the wrong thing.
      RELEASE_TAG: ${{ inputs.tag || github.ref_name }}
    steps:
      - uses: actions/checkout@v7
        with:
          # And the source has to be the tag's, not the branch the dispatch ran
          # from — otherwise VERSION and the release notes come from wherever
          # main happens to be.
          ref: ${{ inputs.tag || github.ref }}
      - name: Validate release metadata
        run: |
          version="${RELEASE_TAG#v}"
          test "$(cat VERSION)" = "$version" || { printf '::error::VERSION과 태그가 일치하지 않습니다.\n'; exit 1; }
          test -s ".github/release-notes/${RELEASE_TAG}.md" || { printf '::error::상세 릴리즈 본문이 없습니다.\n'; exit 1; }
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v7
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - name: Verify source
        run: |
          go test ./...
          go vet ./...
          npm --prefix frontend ci
          npm --prefix frontend run lint
          # Half of what is being published is the frontend, and until now the
          # release ran its linter but never its tests. CI ran them, which is
          # the gate for merging — this is the gate for publishing, and the two
          # came apart once already: v0.158.0 shipped while CI was red.
          npm --prefix frontend test
          # CI runs these too, but CI and this workflow start at the same moment
          # on the same push: no check in CI can stop a publish. Anything that
          # decides whether what is being published is correct has to run here.
          #
          # The deployment files carry the image tag an operator will pull, the
          # documentation ships beside the archive, and the frontend invariant
          # is about the same build. The slow test-quality checks stay in CI —
